import{St as e,at as t,it as n,n as r,st as i,vt as a}from"./chunks/framework.yntlMcNk.js";var o=JSON.parse(`{"title":"Kataloge","description":"","frontmatter":{"title":"Kataloge","covers":{"screens":["SCR-020","SCR-028"],"stories":["US-046","US-047","US-048","US-049","US-050","US-080"]}},"headers":[],"relativePath":"de/usage/catalogs.md","filePath":"de/usage/catalogs.md"}`),s={name:`de/usage/catalogs.md`};function c(r,o,s,c,l,u){let d=e(`Screenshot`);return a(),n(`div`,null,[o[0]||=t(`<h1 id="kataloge" tabindex="-1">Kataloge <a class="header-anchor" href="#kataloge" aria-label="Permalink to “Kataloge”">​</a></h1><p>Ein Katalog ist eine wiederverwendbare Tabellenansicht des Repositorys. Er zeigt die Entitäten eines Entitätstyps als Zeilen. Du brauchst die Berechtigung <code>entity:read</code> (zum Beispiel die Rolle <code>viewer</code>), um Kataloge zu sehen und persönliche anzulegen; geteilte Kataloge brauchen <code>catalog:manage</code> (Rolle <code>enterprise-architect</code>).</p><h2 id="katalog-anlegen" tabindex="-1">Katalog anlegen <a class="header-anchor" href="#katalog-anlegen" aria-label="Permalink to “Katalog anlegen”">​</a></h2><ol><li><p>Wähle <em>Kataloge</em> in der Kopfzeile, dann <em>Neuer Katalog</em>.</p></li><li><p>Fülle den Dialog <em>Neuer Katalog</em> aus:</p><table tabindex="0"><thead><tr><th>Feld</th><th>Bedeutung</th></tr></thead><tbody><tr><td>Name</td><td>Pflicht; eindeutig in der Instanz, unabhängig von Groß- und Kleinschreibung</td></tr><tr><td>Beschreibung</td><td>optional, bis zu 1000 Zeichen</td></tr><tr><td>Primärer Entitätstyp</td><td>Pflicht; seine Entitäten werden die Zeilen der Tabelle</td></tr><tr><td>Sichtbarkeit</td><td><em>Geteilt</em>: für alle Benutzer der Instanz sichtbar (braucht die Berechtigung, Kataloge zu verwalten); <em>Persönlich</em>: nur für dich sichtbar</td></tr><tr><td>Standard-Verknüpfungsmodus</td><td><em>Zusammengefasst</em>: eine Zeile pro Entität, verknüpfte Entitäten in einer Zelle; <em>Zeilen</em>: eine Zeile pro verknüpfter Entität. Gilt für später hinzugefügte Joins</td></tr></tbody></table></li></ol>`,4),i(d,{name:`catalog-create`,alt:`Dialog Neuer Katalog mit Name, Beschreibung, Entitätstyp und Sichtbarkeit`}),o[1]||=t(`<ol start="3"><li>Wähle <em>Katalog anlegen</em>. Der neue Katalog öffnet sich.</li></ol><p>Ist der Name schon vergeben, sagt dir das der Dialog; wähle einen anderen Namen. Ohne die Berechtigung, Kataloge zu verwalten, ist <em>Geteilt</em> nicht wählbar.</p><h2 id="katalog-durchsehen" tabindex="-1">Katalog durchsehen <a class="header-anchor" href="#katalog-durchsehen" aria-label="Permalink to “Katalog durchsehen”">​</a></h2><p>Die Liste <em>Kataloge</em> zeigt jeden Katalog, den du sehen darfst, markiert mit <em>Geteilt</em> oder <em>Persönlich</em>. Öffne einen, um seine Tabelle zu sehen:</p>`,4),i(d,{name:`catalogs`,alt:`Liste der Kataloge`}),i(d,{name:`catalog-table`,alt:`Tabelle eines Katalogs mit Anwendungskomponenten`}),o[2]||=t(`<ul><li>Namen von Entitätstypen, Spaltenköpfe und Werte von Enum-Eigenschaften erscheinen in deiner Sprache, wo deine Organisation sie übersetzt hat (siehe <a href="./login#your-profile">Dein Profil</a>).</li><li>Solange keine Spalten konfiguriert sind (siehe <a href="#configure-columns">Spalten konfigurieren</a>), zeigt die Tabelle die Spalten <em>Name</em> und – wenn der Entitätstyp die Eigenschaft <em>Status</em> hat – <em>Status</em>.</li><li>Werte einer Aufzählungs-Eigenschaft wie <em>Status</em> werden in der Reihenfolge der Werte sortiert, nicht alphabetisch; Einträge ohne Wert kommen zuletzt.</li><li>Klicke auf einen Spaltenkopf, um zu sortieren: aufsteigend, absteigend und zurück zur Standardreihenfolge.</li><li>Die Tabelle zeigt 50 Einträge pro Seite; mit der Seitennavigation unter der Tabelle wechselst du zwischen den Seiten.</li><li>Sortierung und Seite sind Teil der Adresse der Seite. Zurücknavigation, Neuladen oder ein geteilter Link stellen dieselbe Ansicht wieder her; ungültige Werte in der Adresse werden ignoriert, und die erste Seite wird in der Standardreihenfolge gezeigt.</li><li>Hat der Entitätstyp noch keine Entitäten, zeigt die Tabelle <em>Keine Einträge gefunden</em>.</li><li>Den persönlichen Katalog einer anderen Person kannst du nicht öffnen; er verhält sich wie ein Katalog, den es nicht gibt (<em>Katalog nicht gefunden</em>).</li></ul><p>Über die API liefert <code>GET /catalogs/{id}/query</code> dieselben Zeilen mit den Parametern <code>page</code> (ab 0), <code>pageSize</code> (1–200, Standard 50) und <code>sort</code> (<code>{field}:{asc|desc}</code>).</p><h2 id="configure-columns" tabindex="-1">Spalten konfigurieren <a class="header-anchor" href="#configure-columns" aria-label="Permalink to “Spalten konfigurieren”">​</a></h2><p>Du bestimmst, welche Attribute ein Katalog zeigt, in welcher Reihenfolge und unter welcher Überschrift. Ein geteilter Katalog verlangt die Berechtigung, Kataloge zu verwalten (<code>catalog:manage</code>, Rolle <code>enterprise-architect</code>); deinen eigenen persönlichen Katalog konfigurierst du selbst.</p><ol><li>Öffne den Katalog und wähle <em>Spalten konfigurieren</em>.</li><li>Der Dialog listet alle Attribute des Entitätstyps: die Felder <em>Name</em>, <em>Beschreibung</em>, <em>Externe ID</em>, <em>Angelegt</em>, <em>Geändert</em> und <em>Version</em> sowie alle Eigenschaften, die dem Entitätstyp zugeordnet sind, auch die geerbten.</li><li>Pro Zeile: <ul><li><em>Sichtbar</em> blendet die Spalte ein oder aus. Eine ausgeblendete Spalte bleibt in der Liste, so kannst du sie später wieder einblenden.</li><li><em>Überschrift</em> ersetzt den Namen des Attributs in der Tabelle, zum Beispiel <em>Betriebsstatus</em> für <em>Status</em>.</li><li><em>Sortierbar</em> bestimmt, ob Lesende nach der Spalte sortieren dürfen.</li></ul></li><li>Ändere die Reihenfolge, indem du eine Zeile ziehst, oder mit den Pfeil-Buttons einer Zeile.</li><li>Wähle unter <em>Standardsortierung</em> die Spalte und Richtung, nach der die Tabelle sortiert ist, solange niemand eine Sortierung gewählt hat.</li><li>Wähle <em>Speichern</em>. Mindestens eine Spalte muss sichtbar sein.</li></ol><p>Eine Eigenschaft, die dem Entitätstyp nicht mehr zugeordnet ist, erscheint als <em>Nicht verfügbar</em> und wird beim Speichern entfernt. Jede Änderung wird im Audit-Trail festgehalten.</p><p>Über die API ersetzt <code>PUT /catalogs/{id}/columns</code> die Liste. Jede Spalte nennt ein Feld (<code>&quot;field&quot;: &quot;name&quot;</code>, <code>description</code>, <code>externalId</code>, <code>createdAt</code>, <code>updatedAt</code>, <code>entityVersion</code>) oder eine Eigenschaft (<code>&quot;propertyDefId&quot;: &quot;…&quot;</code>), mit <code>displayLabel</code>, <code>visible</code>, <code>sortable</code> und höchstens einer <code>defaultSortDirection</code> (<code>asc</code> oder <code>desc</code>). Eine leere Liste stellt die Standardspalten wieder her.</p><h2 id="joins" tabindex="-1">Joins <a class="header-anchor" href="#joins" aria-label="Permalink to “Joins”">​</a></h2><p>Ein Join zeigt verbundene Entitäten neben jedem Eintrag des Katalogs, zum Beispiel alle Schnittstellen einer Anwendung. Er folgt einem Verbindungstyp des Metamodells, etwa <em>Data Flow</em>. Joins konfigurierst du wie Spalten: Ein geteilter Katalog verlangt die Berechtigung, Kataloge zu verwalten; deinen eigenen persönlichen Katalog konfigurierst du selbst.</p><ol><li>Öffne den Katalog und wähle <em>Joins</em>. Der Dialog listet die Joins des Katalogs.</li><li>Wähle <em>Join hinzufügen</em> und gehe durch die vier Schritte: <ol><li><em>Verbindungstyp</em>: Angeboten werden nur Verbindungstypen, die den Entitätstyp des Katalogs verbinden.</li><li><em>Richtung</em>: <em>Ausgehend</em> folgt Verbindungen, die beim Eintrag beginnen, <em>Eingehend</em> solchen, die bei ihm enden, <em>Beide Richtungen</em> beiden; eine Entität, die in beiden Richtungen erreicht wird, erscheint einmal.</li><li><em>Zieltyp</em>: nur Entitätstypen, die der Verbindungstyp an seinem anderen Ende erlaubt.</li><li><em>Name</em>, <em>Standardmodus</em> und die Spalten des Zieltyps, gewählt wie unter <a href="#configure-columns">Spalten konfigurieren</a>. Der Name wird zur Überschrift über den Spalten des Joins.</li></ol></li><li>Wähle <em>Speichern</em>. Die Tabelle zeigt den Join als Gruppe von Spalten.</li></ol><p><em>Bearbeiten</em> ändert einen Join, <em>Entfernen</em> entfernt ihn. Ein Join, dessen Verbindungstyp oder Zieltyp nicht mehr existiert oder die Entitätstypen nicht mehr verbindet, erscheint als <em>Nicht verfügbar</em> und fehlt in der Tabelle. Ein Katalog hat höchstens 10 Joins. Jede Änderung wird im Audit-Trail festgehalten.</p><h3 id="kompakt-oder-zeilen" tabindex="-1">Kompakt oder Zeilen <a class="header-anchor" href="#kompakt-oder-zeilen" aria-label="Permalink to “Kompakt oder Zeilen”">​</a></h3><p>Jeder Join hat in seiner Überschrift den Umschalter <em>Kompakt / Zeilen</em>:</p><ul><li><em>Kompakt</em> zeigt eine Zeile pro Eintrag; eine Zelle listet alle verbundenen Entitäten, eine pro Zeile. Ein Eintrag ohne verbundene Entitäten behält seine Zeile mit einer leeren Zelle.</li><li><em>Zeilen</em> zeigt eine Zeile pro verbundener Entität; der Eintrag wiederholt sich. In diesem Modus kannst du auch nach einer Spalte des Joins sortieren, und die Seite zählt Zeilen.</li></ul><p>Der Umschalter ändert nur deine Ansicht, nicht den Katalog. Er ist Teil der Adresse der Seite, wie Sortierung und Seite. Stehen mehrere Joins auf <em>Zeilen</em>, bekommt jede Kombination ihrer verbundenen Entitäten eine eigene Zeile. Beim Öffnen des Katalogs gilt der <em>Standardmodus</em> des Joins, sonst der Standard-Join-Modus des Katalogs.</p><p>Über die API fügt <code>POST /catalogs/{id}/joins</code> einen Join hinzu, mit <code>name</code>, <code>connectionMetatypeId</code>, <code>joinDirection</code> (<code>outbound</code>, <code>inbound</code>, <code>both</code>), <code>targetMetatypeId</code>, <code>targetColumns</code> (wie die Spalten, ohne Standardsortierung) und <code>defaultJoinMode</code> (<code>rows</code>, <code>aggregate</code> oder <code>null</code>). <code>PUT</code> und <code>DELETE /catalogs/{id}/joins/{joinId}</code> ändern und entfernen ihn. Die Abfrage liefert die Ergebnisse jedes Joins in <code>joinResults</code> unter der ID des Joins; <code>joinMode[{joinId}]=rows</code> schaltet einen Join für eine Abfrage um, und <code>sort={joinId}.{key}:asc</code> sortiert im Zeilenmodus nach einer Spalte des Joins.</p><h2 id="connection-catalogs" tabindex="-1">Verbindungskataloge <a class="header-anchor" href="#connection-catalogs" aria-label="Permalink to “Verbindungskataloge”">​</a></h2><p>Ein Katalog kann auch Verbindungen auflisten, zum Beispiel alle Datenflüsse zwischen Anwendungen. Wähle beim Erstellen des Katalogs einen Verbindungstyp als <em>Primärer Entitätstyp</em>; der Dialog listet die Entitätstypen unter <em>Elemente</em> und die Verbindungstypen unter <em>Verbindungen</em>.</p><ul><li>Jede Verbindung wird zu einer Zeile. Solange keine Spalten konfiguriert sind, zeigt die Tabelle <em>Quelle</em>, <em>Name</em> und <em>Ziel</em>: die Entität, bei der die Verbindung beginnt, die Verbindung selbst und die Entität, bei der sie endet.</li><li><em>Spalten konfigurieren</em> listet auch die Attribute der Quelle und des Ziels, zum Beispiel <em>Quelle: Vendor</em>. Angeboten werden die Felder und die Eigenschaften der Entitätstypen, die der Verbindungstyp an diesem Ende erlaubt, samt ihren Untertypen; ein Verbindungstyp ohne solche Einschränkung bietet jede Eigenschaft an. Hat die Entität an diesem Ende die Eigenschaft nicht, bleibt die Zelle leer.</li><li>Diese Spalten sortierst du wie jede andere Spalte. Ist die Quelle oder das Ziel gelöscht, bleiben ihre Zellen leer.</li><li>Ein Join beginnt bei der Verbindung selbst, zum Beispiel von einem Datenfluss zu den Datenobjekten, die er transportiert. Beginnt oder endet kein Verbindungstyp beim Verbindungstyp des Katalogs, sagt der Dialog <em>Joins</em> das.</li></ul><p>Über die API trägt eine Spalte der Quelle oder des Ziels <code>&quot;endpoint&quot;: &quot;source&quot;</code> oder <code>&quot;target&quot;</code>, und ihr Schlüssel in der Abfrage ist <code>source.{key}</code> oder <code>target.{key}</code>, zum Beispiel <code>sort=source.name:asc</code>.</p>`,20)])}var l=r(s,[[`render`,c]]);export{o as __pageData,l as default};